const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),date=s=>s?new Date(/(?:Z|[+-]\d{2}:\d{2})$/.test(s)?s:s+'Z').toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—';
const statusNames={pending:'Pendente',approved:'Aprovada (simulada)',rejected:'Rejeitada',confirmed:'Confirmado',shipped:'Enviado',completed:'Concluído',cancelled:'Cancelado'};
let sellerProceeds=[];
let state={catalog:[],orders:[],campaigns:[],approvals:[]},history=[],editAction=null;
function notice(message,error=false){$('notice').hidden=false;$('notice').className=error?'error':'';$('notice').textContent=message;}
async function api(path,method='GET',body){let r=await fetch('/api/v1'+path,{method,headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(r.status===401){location.href='/login';throw Error('Entre para continuar.')}let data=await r.json().catch(()=>({}));if(!r.ok){let d=data.detail;throw Error(typeof d==='string'?d:Array.isArray(d)?d.map(x=>x.msg).join('; '):'Não foi possível concluir. Tente novamente.')}return data;}
async function run(fn){try{await fn()}catch(e){notice(e.message,true)}}
function productName(id){return state.catalog.find(x=>x.id===id)?.name||state.archivedCatalog?.find(x=>x.id===id)?.name||`Produto #${id}`}
function badge(s){return `<span class="badge ${esc(s)}">${esc(statusNames[s]||s)}</span>`}
function showTab(id){document.body.dataset.page=id;document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));$('title').textContent=document.querySelector(`[data-tab="${id}"] .nav-text`).textContent;window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>showTab(b.dataset.go));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));showTab('home');
function proposal(p){if(!p)return '<p>Proposta antiga sem detalhes. Crie uma nova para revisar.</p>';return `<h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p>`+[['Benefícios',p.benefits],['Riscos',p.risks],['Premissas',p.assumptions]].map(([t,a])=>`<b>${t}</b><ul>${(a||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')+`<p><b>Próximo passo:</b> ${esc(p.next_step)}</p>`;}
function renderApprovals(){let filter=$('approvalFilter').value;let rows=state.approvals.filter(x=>!filter||x.status===filter);$('approvalRows').innerHTML=rows.map(a=>`<div class="card"><small>#${a.id} · ${date(a.requested_at)}</small> ${badge(a.status)}${proposal(a.payload.proposal)}<p class="muted">${esc(a.risk_note)}</p>${a.status==='pending'?`<button data-approve="${a.id}">Aprovar simulação</button> <button class="secondary" data-reject="${a.id}">Rejeitar</button>`:`<small>Decisão por ${esc(a.decided_by)} · ${date(a.decided_at)}</small>`}</div>`).join('')||'<p>Nenhuma aprovação neste filtro.</p>';}
function renderCatalog(){let search=$('search').value.toLocaleLowerCase('pt-BR');$('catalogRows').innerHTML=state.catalog.filter(p=>`${p.name} ${p.sku} ${p.brand}`.toLocaleLowerCase('pt-BR').includes(search)).map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku)} · ${esc(p.brand)}</small>${p.stock_profile?.mode==='owned'?'<small>Estoque próprio · aquisição R$ 0,00 · sem reposição de compra</small>':''}</td><td>${brl(p.price)}</td><td>${p.marketplace_stock} / ${p.local_stock??'não conferido'}</td><td>${sellerProceeds.find(q=>q.product_id===p.id)?.state==='estimated'?proceedsCatalog(p.id):p.economics?`${brl(p.economics.profit)} / ${p.economics.margin??'—'}%<small>Preço para meta: ${p.economics.target_price===null?'—':brl(p.economics.target_price)}</small>`:p.stock_profile?.mode==='owned'?'Consulte quanto sobra pela API':'Cadastre os custos'}</td><td>${p.sku.startsWith('meli:')?`<button data-manage-listing="${p.id}">Gerenciar anúncio</button>`:''}<button data-origin="${p.id}" class="secondary">Origem do estoque</button><button data-proceeds="${p.id}">Quanto sobra</button><button data-cost="${p.id}" class="secondary">Custos adicionais</button><button data-stock="${p.id}" class="secondary">Estoque local</button><button data-price="${p.id}" class="secondary">Propor preço</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum produto. Importe seus anúncios ou cadastre um produto local.</td></tr>';}
async function load(){let [overview,catalog,orders,campaigns,approvals,audit,movements,archivedCatalog]=await Promise.all(['/overview','/catalog','/orders','/campaigns','/approvals','/audit','/stock-movements','/catalog/archived'].map(p=>api(p)));state={catalog,orders,campaigns,approvals,overview,archivedCatalog};renderArchivedCatalog();$('alertCount').textContent=overview.alerts.length;
$('alerts').innerHTML=overview.alerts.map(a=>`<div class="alert"><span class="alert-dot" aria-hidden="true">!</span><span>${esc(a.message)}</span></div>`).join('')||'<div class="empty-state">✓ Tudo em dia pelas regras locais.</div>';
$('connection').textContent=overview.marketplace_connected?'Há uma conta cadastrada. A validade será verificada ao importar.':'Conta ainda não conectada.';
document.querySelectorAll('.productSelect').forEach(s=>{let value=s.value;s.innerHTML='<option value="">Selecione…</option>'+catalog.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');s.value=value});renderCatalog();renderApprovals();
$('orderRows').innerHTML=orders.map(o=>`<div class="card"><b>${esc(o.reference)}</b> ${badge(o.status)}<p>${esc(productName(o.product_id))} · ${o.quantity} unidade(s) · ${brl(o.total)}</p><small>${date(o.created_at)}</small><div class="toolbar">${({pending:['confirmed','cancelled'],confirmed:['shipped','cancelled'],shipped:['completed']}[o.status]||[]).map(s=>`<button data-order="${o.id}" data-status="${s}">${{confirmed:'Confirmar e baixar estoque',shipped:'Marcar enviado',completed:'Concluir',cancelled:'Cancelar'}[s]}</button>`).join('')}</div></div>`).join('')||'<p>Nenhum pedido local cadastrado.</p>';
$('campaignRows').innerHTML=campaigns.map(c=>`<div class="card"><h3>${esc(c.name)}</h3>${badge(c.status)}<p>${esc(productName(c.product_id))} · ${brl(c.budget)} propostos</p><p>${esc(c.objective)}</p><small>Aprovação #${c.approval_id} · sem execução externa</small></div>`).join('')||'<p>Nenhum rascunho.</p>';
$('auditRows').innerHTML=audit.map(e=>`<div class="event"><b>${esc(e.event_type)}</b> · ${esc(e.entity_type)} #${esc(e.entity_id)}<small>${date(e.created_at)} · ${esc(JSON.stringify(e.detail))}</small></div>`).join('')||'<p>Nenhum evento.</p>';
$('movementRows').innerHTML=movements.map(m=>`<div class="event">${esc(productName(m.product_id))} · ${m.delta>0?'+':''}${m.delta} unidade(s)<small>${esc(m.reason)} · ${esc(m.actor)} · ${date(m.created_at)}</small></div>`).join('')||'<p>Nenhuma movimentação.</p>';await loadMarketplaceOrders();renderPricingCosts();await loadPricingHistory();await loadReplenishment();await loadDataHub();await loadBackupStatus();await loadListingPlans();}
$('refresh').onclick=()=>run(load);$('search').oninput=renderCatalog;$('approvalFilter').onchange=renderApprovals;
$('sync').onclick=()=>run(async()=>{let b=$('sync');b.disabled=true;try{let r=await api('/integrations/mercadolivre/sync-listings','POST');await load();notice(`${r.imported} anúncio(s) conferido(s); ${r.archived??0} arquivado(s).${r.partial?' Consulta incompleta: registros sem confirmação foram preservados.':''} Estoque local preservado.`)}finally{b.disabled=false}});
function openEditor(title,fields,action){$('editTitle').textContent=title;$('editFields').innerHTML=fields.map(f=>f.options?`<label>${esc(f.label)}<select name="${f.name}">${f.options.map(([value,label])=>`<option value="${esc(value)}" ${value===f.value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`:`<label>${esc(f.label)}<input name="${f.name}" type="${f.type||'text'}" value="${esc(f.value??'')}" ${f.type==='number'?`step="${f.step||'0.01'}" min="${f.min??0}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.required===false?'':'required'} maxlength="${f.maxlength||500}"></label>`).join('');editAction=action;$('editor').showModal();}
$('closeEditor').onclick=()=>$('editor').close();$('editForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{await editAction(Object.fromEntries(new FormData(e.target)));$('editor').close();await load();notice('Alteração local salva.')}finally{b.disabled=false}})};
$('addProduct').onclick=()=>openEditor('Cadastrar produto local',[{name:'sku',label:'SKU único',maxlength:64},{name:'name',label:'Nome',maxlength:160},{name:'brand',label:'Marca',maxlength:64},{name:'reference_price',label:'Preço de referência (R$)',type:'number',min:0.01},{name:'stock',label:'Estoque de referência (não físico)',type:'number',step:1}],v=>api('/products','POST',{...v,reference_price:+v.reference_price,stock:+v.stock}));
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;
if(b.dataset.origin){let p=state.catalog.find(p=>p.id===+b.dataset.origin);openEditor(`Origem · ${p.name}`,[{name:'mode',label:'Origem dos produtos',value:p.stock_profile?.mode||'resale',options:[['owned','Estoque próprio sem compra'],['resale','Revenda com reposição']]},{name:'acquisition_cost',label:'Custo de aquisição por unidade (R$; zero para estoque próprio)',type:'number',value:p.stock_profile?.acquisition_cost??p.economics?.cost??'',required:false}],v=>api(`/products/${p.id}/stock-profile`,'PUT',{mode:v.mode,acquisition_cost:v.acquisition_cost===''?null:v.acquisition_cost}));}
if(b.dataset.cost){let p=state.catalog.find(p=>p.id===+b.dataset.cost),v=p.economics||{};openEditor(`Custos · ${p.name}`,[['cost','Custo unitário (R$)'],['fee_percent','Tarifa (%)'],['shipping','Frete por unidade (R$)'],['tax_percent','Impostos (%)'],['minimum_margin','Margem mínima (%)'],['minimum_stock','Estoque mínimo (0 sem reposição)']].map(([name,label])=>({name,label,type:'number',value:costDefault(p,v,name),step:name==='minimum_stock'?1:0.01,max:name.includes('percent')||name==='minimum_margin'?99:10000000})),values=>api(`/products/${p.id}/economics`,'PUT',values));}
if(b.dataset.price){let p=state.catalog.find(p=>p.id===+b.dataset.price);openEditor('Proposta de preço para aprovação',[{name:'proposed_price',label:'Preço proposto (R$)',type:'number',min:0.01,value:p.price},{name:'reason',label:'Motivo (mínimo 5 caracteres)'}],v=>api(`/products/${p.id}/price-proposals`,'POST',v));}
if(b.dataset.stock){openEditor('Ajustar estoque físico local',[{name:'delta',label:'Variação (+ entrada / − saída). A primeira entrada começa em zero.',type:'number',step:1,min:-1000000},{name:'reason',label:'Motivo (mínimo 3 caracteres)'},{name:'actor',label:'Responsável (mínimo 2 caracteres)',maxlength:120}],v=>api(`/products/${b.dataset.stock}/stock`,'POST',{...v,delta:+v.delta}));}
if(b.dataset.approve||b.dataset.reject){let id=b.dataset.approve||b.dataset.reject;openEditor('Registrar decisão simulada',[{name:'actor',label:'Responsável pela decisão',maxlength:120}],v=>api(`/approvals/${id}/decision`,'POST',{actor:v.actor,approved:!!b.dataset.approve}));}
if(b.dataset.order){openEditor('Registrar status do pedido',[{name:'actor',label:'Responsável',maxlength:120}],v=>api(`/orders/${b.dataset.order}/status`,'POST',{actor:v.actor,status:b.dataset.status}));}});
for(let [form,path,numbers] of [['orderForm','/orders',['product_id','quantity']],['campaignForm','/campaigns',['product_id']]]){$(form).onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let v=Object.fromEntries(new FormData(e.target));numbers.forEach(k=>v[k]=+v[k]);await api(path,'POST',v);e.target.reset();await load();notice('Registro local criado.')}finally{b.disabled=false}})}}
$('chatForm').onsubmit=e=>{e.preventDefault();run(async()=>{let text=$('message').value.trim();if(!text)return;let b=e.submitter;b.disabled=true;try{$('chat').insertAdjacentHTML('beforeend',`<div class="bubble user">${esc(text)}</div>`);let r=await api('/chat','POST',{message:text,history:history.slice(-12)});$('chat').insertAdjacentHTML('beforeend',`<div class="bubble">${esc(r.answer)}${r.proposal?proposal(r.proposal):''}</div>`);history.push({role:'user',content:text},{role:'assistant',content:r.answer});$('message').value='';$('chat').scrollTop=$('chat').scrollHeight;await load()}finally{b.disabled=false}})};
$('changePasswordForm').onsubmit=e=>{e.preventDefault();run(async()=>{let button=e.submitter;button.disabled=true;try{let response=await fetch('/session/password',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});let result=await response.json();if(!response.ok)throw Error(result.detail||'Não foi possível trocar a senha.');e.target.reset();notice('Senha alterada. As sessões anteriores foram encerradas.');}finally{button.disabled=false;}});};
$('logout').onclick=()=>run(async()=>{await fetch('/session',{method:'DELETE'});location.href='/login'});

$('globalSearch').onsubmit=e=>{e.preventDefault();$('search').value=$('globalQuery').value;showTab('catalog');renderCatalog();$('search').focus();};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('globalQuery').focus();}});
function setAppearance(dark){document.documentElement.dataset.theme=dark?'dark':'light';$('themeToggle').setAttribute('aria-label',dark?'Ativar aparência clara':'Ativar aparência escura');try{localStorage.setItem('manager-appearance',dark?'dark':'light')}catch{}}
let preferredAppearance;try{preferredAppearance=localStorage.getItem('manager-appearance')}catch{}
setAppearance(preferredAppearance?preferredAppearance==='dark':matchMedia('(prefers-color-scheme: dark)').matches);
$('themeToggle').onclick=()=>setAppearance(document.documentElement.dataset.theme!=='dark');
$('todayLabel').textContent=new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date());

let mlOffset=0,mlTotal=0;
const mlNames={paid:'Pago',confirmed:'Aguardando pagamento',payment_required:'Aguardando pagamento',payment_in_process:'Pagamento em análise',partially_paid:'Pagamento parcial',partially_refunded:'Reembolso parcial',cancelled:'Cancelado',pending_cancel:'Cancelamento pendente',invalid:'Inválido'};
const syncNames={success:'Concluída',partial:'Parcial',failed:'Falhou',running:'Em andamento'};
function currencyAmount(value,currency){try{return new Intl.NumberFormat('pt-BR',{style:'currency',currency}).format(Number(value))}catch{return `${value} ${currency}`}}
function setOrderSource(manual){$('manualOrders').hidden=!manual;$('mlOrders').hidden=manual;$('showMLOrders').classList.toggle('active',!manual);$('showManualOrders').classList.toggle('active',manual);$('showMLOrders').setAttribute('aria-pressed',String(!manual));$('showManualOrders').setAttribute('aria-pressed',String(manual));}
$('showMLOrders').onclick=()=>setOrderSource(false);$('showManualOrders').onclick=()=>setOrderSource(true);
async function loadMarketplaceOrders(){let query=new URLSearchParams({offset:mlOffset,limit:50,q:$('mlQuery').value.trim()});if($('mlStatus').value)query.set('status',$('mlStatus').value);let [page,summary,runs]=await Promise.all([api('/marketplace-orders?'+query),api('/marketplace-orders/summary'),api('/sync-runs')]);mlTotal=page.total;
$('mlSummary').innerHTML=`<div class="card"><span class="card-kicker">BASE IMPORTADA</span><h2>${summary.count} pedido(s)</h2><p class="muted">Total armazenado das importações realizadas.</p></div><div class="card"><span class="card-kicker">PEDIDOS COM STATUS PAGO</span><h2>${Object.entries(summary.paid_totals).map(([c,v])=>esc(currencyAmount(v,c))).join(' · ')||'Nenhum pedido pago importado'}</h2><p class="muted">Valor bruto na base importada. Não é saldo recebido nem conciliação de pagamentos.</p></div>`;
let last=summary.last_sync;$('mlSyncStatus').textContent=last?`${syncNames[last.status]||last.status} · ${last.count} pedido(s) · janela de ${last.days} dias · ${date(last.finished_at)}. ${last.note}`:'Importe seus pedidos para começar. Se a conta ainda não estiver conectada, acesse Ajustes.';
$('mlOrderRows').innerHTML=page.results.map(o=>`<article class="card imported-order"><div class="card-heading"><div><span class="card-kicker">MERCADO LIVRE · ${date(o.created_at)}</span><h2>Pedido #${esc(o.id)}</h2></div><span class="badge">${esc(mlNames[o.status]||o.status)}</span></div><ul>${o.items.map(i=>`<li><b>${esc(i.title||i.item_id)}</b><small>${i.quantity} unidade(s) × ${esc(currencyAmount(i.unit_price,o.currency))}${i.variation_id?` · Variação ${esc(i.variation_id)}`:''}</small></li>`).join('')}</ul><p><b>Total bruto: ${esc(currencyAmount(o.total,o.currency))}</b></p><small class="muted">Atualizado na origem: ${date(o.updated_at)} · Importado: ${date(o.imported_at)}. Status de pagamento não representa status de entrega.</small></article>`).join('')||'<div class="card empty-state">Nenhum pedido importado neste filtro. Importe um período ou ajuste a busca.</div>';
$('mlPage').textContent=mlTotal?`${mlOffset+1}–${Math.min(mlOffset+50,mlTotal)} de ${mlTotal}`:'0 pedidos';$('mlPrevious').disabled=mlOffset===0;$('mlNext').disabled=mlOffset+50>=mlTotal;
$('syncRunRows').innerHTML=runs.map(r=>`<div class="event"><b>${esc(syncNames[r.status]||r.status)}</b> · ${r.count} pedido(s) · ${r.days} dias<small>${date(r.started_at)} · ${esc(r.note)}</small></div>`).join('')||'<p class="muted">Nenhuma tentativa registrada.</p>';
}
$('mlStatus').onchange=()=>run(async()=>{mlOffset=0;await loadMarketplaceOrders()});$('mlSearchForm').onsubmit=e=>{e.preventDefault();run(async()=>{mlOffset=0;await loadMarketplaceOrders()})};
$('mlPrevious').onclick=()=>run(async()=>{mlOffset=Math.max(0,mlOffset-50);await loadMarketplaceOrders()});$('mlNext').onclick=()=>run(async()=>{mlOffset+=50;await loadMarketplaceOrders()});
$('syncOrders').onclick=()=>run(async()=>{let b=$('syncOrders');b.disabled=true;b.textContent='Importando…';try{let result=await api('/integrations/mercadolivre/sync-orders?days='+$('mlDays').value,'POST');mlOffset=0;await loadMarketplaceOrders();notice(`${result.imported} pedido(s) lido(s) de ${result.total_found} encontrado(s). ${result.message}`,result.partial)}catch(e){await loadMarketplaceOrders();throw e}finally{b.disabled=false;b.textContent='Importar pedidos'}});


let activeSimulation=null,pricingHistory=[];
function renderPricingCosts(){let p=state.catalog.find(p=>p.id===+$('pricingProduct').value);$('pricingEditCosts').disabled=!p;if(!p){$('pricingCosts').textContent='Selecione um produto para conferir as premissas.';return}let e=p.economics;$('pricingCosts').textContent=e?`Preço atual ${brl(p.price)} · Custo ${brl(e.cost)} · Frete ${brl(e.shipping)} · Tarifa ${e.fee_percent}% · Imposto ${e.tax_percent}% · Meta ${e.minimum_margin}%`:'Este produto ainda precisa de custos cadastrados. Clique em Conferir custos e margem.';}
$('pricingProduct').onchange=renderPricingCosts;
$('pricingEditCosts').onclick=()=>{let p=state.catalog.find(p=>p.id===+$('pricingProduct').value);if(!p)return;let v=p.economics||{};openEditor(`Custos · ${p.name}`,[['cost','Custo unitário (R$)'],['fee_percent','Tarifa (%)'],['shipping','Frete por unidade (R$)'],['tax_percent','Impostos (%)'],['minimum_margin','Margem mínima (%)'],['minimum_stock','Estoque mínimo (0 sem reposição)']].map(([name,label])=>({name,label,type:'number',value:costDefault(p,v,name),step:name==='minimum_stock'?1:0.01,max:name.includes('percent')||name==='minimum_margin'?99:10000000})),values=>api(`/products/${p.id}/economics`,'PUT',values));};
function showSimulation(sim){activeSimulation=sim;const a=sim.assumptions;$('pricingResult').innerHTML=`<div class="card"><div class="card-heading"><div><span class="card-kicker">SIMULAÇÃO #${sim.id} · ${date(sim.created_at)}</span><h2>${esc(a.name)}</h2></div></div><div class="pricing-totals"><div><small>Piso para sua margem</small><strong>${brl(sim.minimum_price)}</strong></div><div><small>Preço de equilíbrio</small><strong>${brl(sim.break_even_price)}</strong></div><div><small>Desconto máximo sobre o preço atual</small><strong>${esc(sim.max_discount_percent)}%</strong></div></div><p class="muted">Meta ${esc(a.minimum_margin)}% · Custo ${brl(a.cost)} · Frete ${brl(a.shipping)} · Tarifa ${esc(a.fee_percent)}% · Imposto ${esc(a.tax_percent)}%. Valores estimados por unidade.</p><div class="table-wrap"><table><thead><tr><th>Cenário</th><th>Preço</th><th>Tarifa / imposto</th><th>Resultado unitário</th><th>Margem</th><th>Próxima decisão</th></tr></thead><tbody>${sim.scenarios.map(r=>`<tr><td><b>${esc(r.label)}</b><small>${Number(r.price_change_percent)>0?'+':''}${esc(r.price_change_percent)}% sobre o atual</small></td><td>${brl(r.price)}</td><td>${brl(r.fee)} / ${brl(r.tax)}</td><td>${brl(r.profit)}</td><td><span class="badge ${r.meets_target?'approved':'rejected'}">${esc(r.margin)}%</span><small>${r.status==='loss'?'Resultado negativo':r.meets_target?'Dentro da meta':'Abaixo da meta'}</small></td><td>${r.price===a.current_price?'Preço atual':r.meets_target?`<button data-sim-scenario="${esc(r.key)}">Criar proposta</button>`:'<small>Ajuste o preço para atingir sua margem.</small>'}</td></tr>`).join('')}</tbody></table></div><p class="muted">${esc(sim.notice)}</p><p class="muted">Piso arredondado para cima em centavos. A referência concorrente é um dado manual; compare modelo, condição e frete. Aprovar uma proposta não publica o preço.</p></div>`;}
async function loadPricingHistory(){pricingHistory=await api('/pricing/simulations');$('pricingHistory').innerHTML=pricingHistory.map(s=>`<div class="event"><b>${esc(s.assumptions.name)}</b> · #${s.id}<small>${date(s.created_at)} · Meta ${esc(s.assumptions.minimum_margin)}% · Piso ${brl(s.minimum_price)}</small><button class="secondary" data-open-simulation="${s.id}">Reabrir cálculo</button></div>`).join('')||'<p class="muted">Nenhuma simulação ainda. Escolha um produto para começar.</p>';}
$('pricingForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let body=Object.fromEntries(new FormData(e.target));body.product_id=+body.product_id;for(let key of ['proposed_price','competitor_price'])if(!body[key])delete body[key];let sim=await api('/pricing/simulate','POST',body);showSimulation(sim);await loadPricingHistory();notice('Simulação salva. Nenhum preço foi alterado.')}finally{b.disabled=false}})};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.openSimulation){let sim=pricingHistory.find(s=>s.id===+b.dataset.openSimulation);if(sim)showSimulation(sim)}if(b.dataset.simScenario&&activeSimulation){const simulationId=activeSimulation.id,scenario=b.dataset.simScenario;openEditor('Criar proposta para aprovação',[{name:'actor',label:'Responsável pela proposta',maxlength:120}],async values=>{let r=await api(`/pricing/simulations/${simulationId}/proposal`,'POST',{actor:values.actor,scenario});notice(`Proposta #${r.approval_id} criada. Revise em Aprovações.`);});}});


let replenishmentRows=[];
const qualityLabels={ready:'Importação recente e completa para a janela selecionada.',missing_history:'Falta uma importação completa de pedidos.',incomplete_history:'A última importação falhou, foi parcial ou cobre um período menor.',stale_history:'A última importação tem mais de 24 horas. Atualize os pedidos.'};
function renderReplenishmentPolicy(){let row=replenishmentRows.find(r=>r.product_id===+$('replenishmentProduct').value);let form=$('replenishmentForm');const defaults={supplier:'',lead_days:'',coverage_days:'',safety_units:0,pack_size:1,minimum_order:1,incoming_units:0,daily_demand:''};for(let key of Object.keys(defaults))form.elements.namedItem(key).value=row?.policy?.[key]??defaults[key];$('replenishmentPolicyNote').textContent=row?.stock_mode==='owned'?'Estoque próprio: fornecedor e reposição de compra não se aplicam.':row?.policy?'Regras locais cadastradas. Revise prazo, demanda e unidades em trânsito antes de salvar.':'Sem regras salvas para este produto. Preencha prazo e cobertura; não presumimos esses valores.';for(let field of form.elements)if(field.name!=='product_id')field.disabled=row?.stock_mode==='owned';}
async function loadReplenishment(){const result=await api('/replenishment/plan?days='+$('replenishmentDays').value+'&stock_source='+$('replenishmentStockSource').value);replenishmentRows=result.results;$('replenishmentQuality').textContent=`${qualityLabels[result.history_quality]||result.history_quality}${result.history_cutoff?' Referência: '+date(result.history_cutoff)+'.':''} Você pode informar demanda manual por produto.`;
const actionable=replenishmentRows.filter(r=>r.can_propose),blocked=replenishmentRows.filter(r=>r.blockers.length);$('replenishmentSummary').innerHTML=`<div class="card"><span class="card-kicker">PARA SUA REVISÃO</span><h2>${actionable.length} reposição(ões)</h2><p class="muted">Quantidade sugerida positiva com as premissas disponíveis.</p></div><div class="card"><span class="card-kicker">ANTES DE CALCULAR</span><h2>${blocked.length} produto(s) com pendências</h2><p class="muted">Custos, estoque físico, demanda ou regras ainda precisam de revisão.</p></div>`;
$('replenishmentRows').innerHTML=replenishmentRows.map(r=>`<article class="card"><div class="card-heading"><div><span class="card-kicker">${esc(r.sku)}</span><h2>${esc(r.name)}</h2></div><span class="badge">${r.stock_mode==='owned'?'Estoque próprio':r.blockers.length?'Dados pendentes':r.suggested_quantity?'Revisar reposição':'Sem reposição calculada'}</span></div><div class="restock-stats"><div><small>Estoque-base (${r.stock_source==='marketplace'?'API':'físico'})</small><b>${r.stock_base??'Não conferido'}</b></div><div><small>Disponível + em trânsito − pendente manual</small><b>${r.available_with_incoming??'—'}</b></div><div><small>Demanda diária</small><b>${r.daily_demand??'Indisponível'}</b></div><div><small>Quantidade sugerida</small><b>${r.suggested_quantity??'—'}</b></div></div><p class="muted">${r.demand_basis==='manual'?'Demanda manual':r.demand_basis==='imported_paid'?`${r.sold_units} unidade(s) em pedidos pagos nos ${r.days} dias da importação`:'Base de demanda indisponível'} · Estoque-alvo ${r.target_stock??'—'} · Cobertura disponível ${r.coverage_days===null?'não calculada':r.coverage_days+' dias'} · Mercadoria estimada ${r.estimated_cost===null?'sem custo':brl(r.estimated_cost)}.</p>${r.policy&&r.stock_mode!=='owned'?`<p class="muted">Fornecedor: ${esc(r.policy.supplier)} · Prazo ${r.policy.lead_days} dias · Cobertura adicional ${r.policy.coverage_days} dias · Segurança ${r.policy.safety_units} un. · Lote ${r.policy.pack_size} un. · Pedido mínimo ${r.policy.minimum_order} un.</p>`:''}<ul class="muted">${[...r.blockers,...r.warnings].map(m=>`<li>${esc(m)}</li>`).join('')}</ul><div class="toolbar">${r.stock_mode==='owned'?'<span class="muted">Reposição de compra não se aplica.</span>':`<button class="secondary" data-restock-config="${r.product_id}">Configurar regras</button>`}${r.can_propose?`<button data-restock-propose="${r.product_id}">Propor reposição</button>`:''}</div></article>`).join('')||'<div class="card empty-state">Importe seus anúncios ou cadastre produtos para começar.</div>';$('replenishmentForm').closest('details').hidden=replenishmentRows.length>0&&replenishmentRows.every(r=>r.stock_mode==='owned');renderReplenishmentPolicy();}
$('replenishmentProduct').onchange=renderReplenishmentPolicy;$('replenishmentStockSource').onchange=()=>run(loadReplenishment);$('replenishmentDays').onchange=()=>run(loadReplenishment);$('refreshReplenishment').onclick=()=>run(loadReplenishment);
$('replenishmentForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let v=Object.fromEntries(new FormData(e.target)),id=+v.product_id;delete v.product_id;for(let k of ['lead_days','coverage_days','safety_units','pack_size','minimum_order','incoming_units'])v[k]=+v[k];if(v.daily_demand==='')v.daily_demand=null;await api(`/replenishment/products/${id}/policy`,'PUT',v);await loadReplenishment();notice('Regras locais salvas. Nenhuma compra foi realizada.')}finally{b.disabled=false}})};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.restockConfig){$('replenishmentProduct').value=b.dataset.restockConfig;renderReplenishmentPolicy();$('replenishmentProduct').focus();}if(b.dataset.restockPropose){let row=replenishmentRows.find(r=>r.product_id===+b.dataset.restockPropose);if(!row)return;const days=$('replenishmentDays').value,stockSource=$('replenishmentStockSource').value;openEditor('Proposta de reposição simulada',[{name:'actor',label:'Responsável pela proposta',maxlength:120}],values=>api(`/replenishment/products/${row.product_id}/proposal?days=${days}&stock_source=${stockSource}`,'POST',{actor:values.actor,fingerprint:row.fingerprint}));}});


function costDefault(product,values,name){if(values[name]!==undefined&&values[name]!==null)return values[name];if(name==='fee_percent'){let fact=apiFacts.find(f=>f.product_id===product.id);if(fact&&fact.fee_fixed_estimate!==null&&Number(fact.fee_fixed_estimate)===0&&fact.fee_percent_estimate!==null)return fact.fee_percent_estimate;}if(name==='cost'&&product.stock_profile?.acquisition_cost!==null&&product.stock_profile?.acquisition_cost!==undefined)return product.stock_profile.acquisition_cost;if(name==='minimum_stock'&&product.stock_profile?.mode==='owned')return 0;return '';}
let apiFacts=[];
let dataHubState=null,dataHubOffset=0,dataHubTotal=0,dataHubTimer=null;
const hubLabels={running:'Consultando',success:'Recebido',empty:'Sem registros',partial:'Parcial',denied:'Sem permissão',unavailable:'Indisponível',failed:'Falhou',blocked:'Depende de outra consulta',pending:'Ainda não consultado',completed:'Concluído',completed_with_gaps:'Concluído com pendências',cancelled:'Interrompido',interrupted:'Interrompido ao reiniciar'};
async function loadDataHub(){let previous=dataHubState?.job?.status,previousJobId=dataHubState?.job?.id;let h=await api('/data-hub/status');dataHubState=h;let j=h.job,progress=j?.progress||{},mods=Object.entries(h.modules),done=mods.filter(([k])=>progress[k]&&progress[k].status!=='running').length;
$('dataHubJob').textContent=j?`Sincronização #${j.id}: ${hubLabels[j.status]||j.status} · ${done}/${mods.length} áreas · Início ${date(j.started_at)}${j.finished_at?' · Fim '+date(j.finished_at):''}.`:h.connected?'Conta conectada. Inicie a sincronização para consultar as áreas.':'Conecte sua conta em Ajustes antes de sincronizar.';
$('dataHubProgress').style.width=Math.round(done/mods.length*100)+'%';$('dataHubCount').textContent=`${mods.length} áreas mapeadas`;$('syncAllData').disabled=!h.connected||j?.status==='running';$('cancelDataSync').hidden=j?.status!=='running';
$('dataHubModules').innerHTML=mods.map(([k,label])=>{let p=progress[k],status=p?.status||'pending';return `<article class="card data-module"><span class="badge ${status==='success'?'approved':['denied','failed','partial'].includes(status)?'pending':''}">${esc(hubLabels[status]||status)}</span><h3>${esc(label)}</h3><strong>${h.counts[k]||0}</strong><small>registro(s) em cache${p?' · '+p.count+' consultado(s)/cache nesta tentativa':''}</small>${p?.action?`<p class="muted">${esc(p.action)}</p>`:''}${p?.errors?.length?`<details><summary>Ver pendências</summary><ul>${p.errors.map(e=>`<li>${esc(e.source||e.issue)}${e.http?' · HTTP '+e.http:''}</li>`).join('')}</ul></details>`:''}<button class="text-button" data-hub-module="${k}">Consultar registros <span>→</span></button></article>`}).join('');
let old=$('dataHubArea').value;$('dataHubArea').innerHTML=mods.map(([k,l])=>`<option value="${k}">${esc(l)}</option>`).join('');if(old)$('dataHubArea').value=old;await loadHubRecords();await loadApiProductFacts();await loadSellerProceeds();await loadApiCompletion();await loadAutoSync();await loadStoreDashboard();
if(dataHubTimer)clearTimeout(dataHubTimer);if(j?.status==='running')dataHubTimer=setTimeout(()=>run(loadDataHub),3000);else if(previous==='running'||(previousJobId&&j?.id!==previousJobId)){await load();notice('Sincronização finalizada. Consulte as pendências de cada área.');}else dataHubTimer=setTimeout(()=>run(loadDataHub),30000);
}
async function loadHubRecords(){let q=new URLSearchParams({module:$('dataHubArea').value,q:$('dataHubQuery').value,offset:dataHubOffset});let r=await api('/data-hub/records?'+q);dataHubTotal=r.total;$('dataHubRecords').innerHTML=r.results.map(v=>`<div class="event"><b>${esc(v.external_id)}</b><small>${esc(v.source)} · ${date(v.fetched_at)}</small><button class="secondary" data-api-record="${v.id}">Abrir detalhes</button></div>`).join('')||'<p class="muted">Nenhum registro em cache nesta área ou neste filtro.</p>';$('dataHubPrevious').disabled=dataHubOffset===0;$('dataHubNext').disabled=dataHubOffset+30>=dataHubTotal;$('dataHubPage').textContent=dataHubTotal?`${dataHubOffset+1}–${Math.min(dataHubOffset+30,dataHubTotal)} de ${dataHubTotal}`:'0 registros';}
async function loadApiProductFacts(){let facts=await api('/data-hub/product-facts');apiFacts=facts;$('apiProductFacts').innerHTML=facts.length?`<div class="card"><span class="card-kicker">PREENCHIDO PELA API</span><h2>Seus anúncios, com contexto.</h2><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Preço / estoque anunciado</th><th>Tarifa total estimada</th><th>Visitas (90 dias)</th><th>Logística</th><th>Coletado</th></tr></thead><tbody>${facts.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.item_id)} · ${esc(p.status)} · ${p.variations} variação(ões)</small></td><td>${currencyAmount(p.price,p.currency||'BRL')} / ${p.available_quantity??'—'}</td><td>${p.fee_amount_estimate===null?'Não disponível':currencyAmount(p.fee_amount_estimate,p.currency||'BRL')}<small>${p.fee_percent_estimate??'—'}% · Componente fixo ${p.fee_fixed_estimate===null?'—':currencyAmount(p.fee_fixed_estimate,p.currency||'BRL')} (já incluído no total)</small></td><td>${p.visits_90_days??'—'}</td><td>${esc(p.logistics||'Não informada')}</td><td>${date(p.fetched_at)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Tarifas são cotações para o anúncio e preço consultados; não são custo de aquisição. Preço e estoque atualizam o catálogo local. Custos e regras informados por você são preservados.</p></div>`:'';}
$('syncAllData').onclick=()=>run(async()=>{let j=await api('/data-hub/sync','POST');notice(`Sincronização #${j.id} iniciada. Você pode acompanhar cada área abaixo.`);await loadDataHub()});$('cancelDataSync').onclick=()=>run(async()=>{await api('/data-hub/cancel','POST');notice('Interrupção solicitada. A consulta atual será concluída antes de parar.');await loadDataHub()});$('refreshDataHub').onclick=()=>run(loadDataHub);
$('dataHubArea').onchange=()=>run(async()=>{dataHubOffset=0;$('dataHubDetail').hidden=true;await loadHubRecords()});$('dataHubSearch').onsubmit=e=>{e.preventDefault();run(async()=>{dataHubOffset=0;await loadHubRecords()})};$('dataHubPrevious').onclick=()=>run(async()=>{dataHubOffset=Math.max(0,dataHubOffset-30);await loadHubRecords()});$('dataHubNext').onclick=()=>run(async()=>{dataHubOffset+=30;await loadHubRecords()});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.hubModule)run(async()=>{$('dataHubArea').value=b.dataset.hubModule;dataHubOffset=0;await loadHubRecords();$('dataHubArea').focus()});if(b.dataset.apiRecord)run(async()=>{let record=await api('/data-hub/records/'+b.dataset.apiRecord);$('dataHubDetail').hidden=false;$('dataHubDetail').textContent=JSON.stringify(record,null,2);$('dataHubDetail').scrollIntoView({block:'start',behavior:'smooth'})});});


async function loadApiCompletion(){let [descriptions,claims,finance,advertising]=await Promise.all([api('/api-details/descriptions'),api('/api-details/claims'),api('/api-details/finance'),api('/api-details/advertising')]);const progress=dataHubState?.job?.progress||{},ads=progress.ads,adsMetrics=progress.ads_metrics;
$('apiCompletionState').innerHTML=[['Descrições',descriptions.length?`${descriptions.filter(d=>d.plain_text).length} texto(s) disponível(is). A origem de cada texto aparece abaixo.`:'Faça uma sincronização para consultar os textos.'],['Publicidade',ads&&['unavailable','denied'].includes(ads.status)?'A API não liberou anunciante nesta conta. Confira em Mercado Livre → Minha conta → Publicidade. O sistema não ativa campanhas nem gera gastos.':`Métricas: ${hubLabels[adsMetrics?.status]||'ainda não consultadas'}. Leitura de cliques, impressões, custos, ROAS e ACOS quando retornados.`],['Reclamações',claims.length?`${claims.length} resumo(s); ${claims.filter(c=>c.detail_state==='restricted').length} com detalhes restritos. O papel comprador/vendedor é identificado abaixo.`:'Nenhum resumo disponível na base importada.'],['Financeiro',finance.results.length?`${finance.results.length} pack(s)/ordem(ns) para conferência de componentes. ${finance.results.filter(r=>r.state==='needs_review').length} com pendências.`:'Não há vendas importadas para conferir. Faturamento e descontos recebidos continuam no explorador.']].map(([title,text])=>`<div class="event"><b>${esc(title)}</b><p class="muted">${esc(text)}</p></div>`).join('');
$('apiAdMetrics').innerHTML=advertising.length?`<div class="table-wrap"><table><thead><tr><th>Campanha</th><th>Período retornado</th><th>Impressões / cliques</th><th>Custo</th><th>Receita atribuída</th><th>ROAS / ACOS</th></tr></thead><tbody>${advertising.map(a=>`<tr><td><b>${esc(a.name)}</b><small>${esc(a.product)} · #${esc(a.campaign_id)}</small></td><td>${esc(a.date_from||'Não informado')} → ${esc(a.date_to||'Não informado')}</td><td>${esc(a.prints??'Pendente')} / ${esc(a.clicks??'Pendente')}</td><td>${a.cost===null?'Pendente':a.currency?esc(currencyAmount(a.cost,a.currency)):esc(a.cost)}</td><td>${a.attributed_revenue===null?'Pendente':a.currency?esc(currencyAmount(a.attributed_revenue,a.currency)):esc(a.attributed_revenue)}</td><td>${esc(a.roas??'Não calculado')} / ${a.acos===null?'Não calculado':esc(a.acos)+'%'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhuma métrica de campanha foi disponibilizada. Confira a situação de Publicidade acima. Não exibimos números fictícios.</p>';
$('apiDescriptions').innerHTML=descriptions.map(d=>`<article class="event"><h3>${esc(d.title||d.item_id)}</h3><span class="badge">${d.origin==='catalog'?'Catálogo oficial':d.origin==='listing'?'Descrição do anúncio':'Texto ausente'}</span><p class="muted">${esc(d.notice||'')} · ${esc(d.source)} · ${date(d.fetched_at)}</p><p class="description-text">${esc(d.plain_text||'A API não forneceu texto.')}</p></article>`).join('')||'<p class="muted">Textos ainda não consultados.</p>';
$('apiClaimAccess').innerHTML=claims.map(c=>`<div class="event"><b>#${esc(c.id)}</b> · ${esc(c.type)} · ${esc(c.status)}<p class="muted">Papel da conta: ${c.account_roles.map(r=>r==='complainant'?'reclamante / geralmente comprador':r==='respondent'?'reclamado / geralmente vendedor':esc(r)).join(', ')}.</p><p class="muted">${esc(c.note)}</p></div>`).join('')||'<p class="muted">Nenhum resumo de reclamação importado.</p>';
$('financeTotals').innerHTML=Object.entries(finance.totals).map(([currency,v])=>`<div class="card"><span class="card-kicker">${esc(currency)} · ORDENS IMPORTADAS</span><h2>${v.gross===null?'Valor bruto pendente':esc(currencyAmount(v.gross,currency))}</h2><p class="muted">Bruto de ${v.groups} pack(s)/ordem(ns). ${v.matched_groups} com componentes conferidos. Não é saldo recebido.</p></div>`).join('');
$('financeRows').innerHTML=finance.results.map(r=>`<article class="card"><div class="card-heading"><h2>Pack / ordem #${esc(r.group_id)}</h2><span class="badge">${r.state==='matched_components'?'Componentes conferidos':'Revisar dados'}</span></div><p class="muted">Ordens: ${r.order_ids.map(esc).join(', ')}</p><div class="restock-stats">${[['Bruto das ordens',r.gross],['Tarifa de venda realizada',r.realized_fee],['Frete do vendedor',r.seller_shipping],['Após tarifa e frete',r.subtotal_before_refunds]].map(([label,value])=>`<div><small>${label}</small><b>${value===null?'Pendente':esc(currencyAmount(value,r.currency||'BRL'))}</b></div>`).join('')}</div>${r.fee_source?'<p class="muted">Fonte da tarifa: '+esc(r.fee_source==='order_items.sale_fee'?'itens da venda, por unidade × quantidade':'pagamentos aprovados')+'.</p>':''}${(r.fee_notes||[]).map(note=>'<p class="muted">'+esc(note)+'</p>').join('')}${r.issues.length?'<ul class="muted">'+r.issues.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':''}<p class="muted">${esc(r.notice)}</p></article>`).join('')||'<div class="card empty-state">Nenhuma venda encontrada na base importada. Os cálculos serão exibidos quando houver pedidos reais disponíveis; não usamos dados fictícios.</div>';
$('financeBilling').innerHTML=(finance.billing||[]).map(b=>`<article class="event"><b>${esc(b.group)} · ${esc(b.document_type)} · ${esc(b.period)}</b> <span class="badge">${{matched:'Componentes conferidos',divergent:'Diferença encontrada',incomplete:'Dados pendentes',no_components:'Sem componentes retornados'}[b.state]||esc(b.state)}</span><small>Cópia mais recente: ${date(b.latest_snapshot)}</small>${b.components.length?`<div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Resumo</th><th>Detalhes</th><th>Diferença</th><th>Situação</th></tr></thead><tbody>${b.components.map(c=>`<tr><td>${esc(c.kind)} / ${esc(c.type)}</td><td>${esc(c.expected??'Pendente')}</td><td>${esc(c.observed??'Pendente')}</td><td>${esc(c.difference??'Pendente')}</td><td>${c.state==='matched'?'Conferido':c.state==='divergent'?'Divergente':'Pendente'}</td></tr>`).join('')}</tbody></table></div>`:''}${b.issues.length?'<ul class="muted">'+b.issues.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':''}</article>`).join('')||'<p class="muted">Nenhum período com resumo e detalhes disponível. Sincronize os dados da conta para consultar.</p>';
}
