let autoSyncDirty=false;
$('autoSyncForm').addEventListener('change',()=>{autoSyncDirty=true;});
async function loadAutoSync(){
 let a=await api('/auto-sync');
 $('saveAutoSync').disabled=!a.connected;
 if(!a.connected){$('autoSyncState').textContent='Conecte sua conta em Ajustes para ativar as atualizações.';return;}
 if(!autoSyncDirty&&!document.activeElement?.closest('#autoSyncForm')){$('autoSyncEnabled').value=String(a.enabled);$('autoSyncInterval').value=String(a.interval_minutes);}
 $('autoSyncState').textContent=a.enabled?`${a.active_job_id?'Consulta automática #'+a.active_job_id+' em acompanhamento. ':''}Frequência: ${a.interval_minutes/60} hora(s). Próxima consulta periódica: ${date(a.next_run_at)}. ${a.failures?'Nova tentativa após falha; '+a.failures+' tentativa(s) sem conclusão.':''}`:'Atualização automática pausada. Você pode sincronizar manualmente.';
 let n=a.notifications; $('autoSyncNotifications').textContent=a.notification_received?`Avisos recebidos: ${n.pending||0} aguardando · ${n.queued||0} em consulta · ${n.checked||0} com consulta concluída. Os dados são sempre lidos da API autenticada.`:'Nenhuma notificação recebida até agora. A atualização periódica já está preparada; o recebimento por evento depende da configuração no Mercado Livre.';
 $('autoSyncHistory').innerHTML=a.history.map(j=>`<div class="event"><b>Sincronização #${j.id} · ${j.trigger==='automatic'?'Automática':'Manual'} · ${esc(hubLabels[j.status]||j.status)}</b><small>${date(j.started_at)}${j.finished_at?' → '+date(j.finished_at):''} · ${j.issues} área(s) com pendências</small></div>`).join('')||'<p class="muted">Nenhuma sincronização registrada.</p>';
}
$('autoSyncForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/auto-sync','PUT',{enabled:$('autoSyncEnabled').value==='true',interval_minutes:Number($('autoSyncInterval').value)});autoSyncDirty=false;notice('Frequência de atualização salva.');await loadAutoSync();});};

async function loadBackupStatus(){
 const b=await api('/maintenance');
 const names={ok:'Cópia atualizada',pending:'Aguardando a primeira cópia',not_configured:'Backup ainda não configurado',stale:'Cópia antiga: conferir o serviço',failed:'Falha na última tentativa'};
 $('backupStatus').innerHTML=`<div class="event"><b>${names[b.backup_state]||'Conferir backup'}</b><small>Última cópia: ${date(b.last_backup_at)} · Próxima: ${date(b.next_backup_at)}</small>${b.tables!==null?`<small>${b.tables} tabelas · ${b.records} registros na cópia</small>`:''}</div><div class="event"><b>${b.verification_state==='failed'?'Teste de recuperação com falha':b.last_verified_at?'Recuperação testada':'Recuperação ainda não testada'}</b><small>${b.last_verified_at?date(b.last_verified_at)+' · '+(b.latest_archive_verified?'A cópia mais recente foi restaurada e conferida.':'O teste se refere a uma cópia anterior.'):'O resultado será exibido após restaurar a cópia em um banco separado.'}</small></div>`;
}
$('refreshBackupStatus').onclick=()=>run(loadBackupStatus);
async function loadStoreDashboard(){
 const d=await api('/store-dashboard?days='+$('storeDays').value);
 const quality={ready:'Janela importada completa e recente',missing:'Histórico ainda não importado',partial:'Importação parcial',insufficient_window:'A importação não cobre toda a janela escolhida',stale:'Dados antigos: atualize a importação',failed_latest_attempt:'A consulta mais recente ficou com pendências'};
 $('storeHistoryState').textContent=`${quality[d.history_quality]||d.history_quality}${d.through?' · De '+date(d.from)+' até '+date(d.through):''}${d.sync_running?' · Sincronização em andamento.':'.'}${!d.confirmed_window?' Os números disponíveis são observações da cópia local, sem confirmar a janela completa.':''}`;
 const totals=Object.entries(d.gross_paid_by_currency);
 const paid=totals.length===1?currencyAmount(totals[0][1],totals[0][0]):totals.length>1?totals.length+' moedas':d.confirmed_window?'Sem vendas pagas':'Aguardando dados';
 const summary=totals.length>1?totals.map(([c,v])=>currencyAmount(v,c)).join(' · '):'Total bruto dos pedidos pagos; não é lucro';
 const metrics=[['Produtos cadastrados',d.products,'Catálogo local da operação'],['Pedidos importados',d.order_count??'—',d.confirmed_window?d.days+' dias na janela importada':'Base incompleta ou não consultada'],['Bruto dos pedidos pagos',paid,summary],['Para sua revisão',state.overview?.pending_approvals??0,'Propostas locais; execução simulada']];
 $('metrics').innerHTML=metrics.map(([label,value,detail])=>`<div class="metric"><div class="metric-top"><span>${esc(label)}</span></div><strong>${esc(value)}</strong><small>${esc(detail)}</small></div>`).join('');
 $('readiness').innerHTML=[['Aquisição confirmada',d.acquisition_confirmed],['Cálculo automático da API',d.automatic_quotes??0],['Estoque importado da API',d.stock_from_api]].map(([label,count])=>`<div class="readiness-item"><div><b>${esc(label)}</b><span>${count} de ${d.products} produtos</span></div><div class="progress-track"><span style="width:${d.products?Math.round(count/d.products*100):0}%"></span></div></div>`).join('');
 $('storeRecentOrders').innerHTML=d.recent_orders.length?`<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Pagamento</th><th>Total bruto</th><th>Criado</th><th>Consulta</th></tr></thead><tbody>${d.recent_orders.map(o=>`<tr><td>#${esc(o.id)}</td><td>${esc(mlNames[o.status]||o.status)}</td><td>${esc(currencyAmount(o.total,o.currency))}</td><td>${date(o.created_at)}</td><td><button class="secondary" data-store-order="${esc(o.id)}">Abrir pedido</button></td></tr>`).join('')}</tbody></table></div>`:`<p class="empty-state">${d.confirmed_window?'Nenhum pedido encontrado nesta janela importada.':'Ainda não há pedidos disponíveis para confirmar esta janela. Confira a importação.'}</p>`;
 $('storeTotalsNotice').textContent=d.notice;
 $('storeChecklistSummary').textContent=d.pending_checks?`${d.pending_checks} etapa(s) precisa(m) de atenção. As pendências de custo não alteram seus anúncios.`:'As verificações locais estão em dia. Confira também as restrições de acesso da API abaixo.';
 $('storeChecklist').innerHTML=d.checks.map(c=>`<div class="store-check"><span class="badge ${c.state==='ready'?'approved':'pending'}">${c.state==='ready'?'Conferido':'Conferir'}</span><h3>${esc(c.label)}</h3><p class="muted">${esc(c.detail)}</p><button class="text-button" ${c.product_id&&c.target!=='pricing'?'data-cost="'+c.product_id+'"':'data-store-target="'+esc(c.target)+'"'}>${c.product_id&&c.target!=='pricing'?'Confirmar despesas':'Consultar'} →</button></div>`).join('');
 $('storeRestrictions').textContent=d.restrictions.length?`${d.restrictions.length} área(s) da última sincronização têm restrições ou pendências. Veja os detalhes em Dados Mercado Livre.`:'Confira a Central de dados para a situação detalhada de cada recurso.';
 $('storeManualSummary').textContent=`${state.overview?.open_orders??0} pedido(s) manual(is) em aberto · ${brl(state.overview?.local_order_revenue??0)} em valor bruto local. Esses valores não são somados aos pedidos do Mercado Livre.`;
}
$('storeDays').onchange=()=>run(loadStoreDashboard);
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.storeTarget){showTab(b.dataset.storeTarget);if(b.dataset.storeTarget==='orders')setOrderSource(false);}if(b.dataset.storeManual){showTab('orders');setOrderSource(true);}if(b.dataset.storeOrder)run(async()=>{showTab('orders');setOrderSource(false);$('mlQuery').value=b.dataset.storeOrder;$('mlStatus').value='';mlOffset=0;await loadMarketplaceOrders();});});

function proceedsCatalog(id){let r=sellerProceeds.find(q=>q.product_id===id);return `${esc(currencyAmount(r.remaining_estimate,r.currency))}<small>Sobra estimada · ${esc(r.remaining_margin_percent)}% · meta ${esc(r.minimum_margin??'—')}%</small>`;}
function proceedsCard(r){let amount=v=>v===null?'Pendente':esc(currencyAmount(v,r.currency||'BRL'));return `<article class="card"><div class="card-heading"><h2>${esc(r.name)}</h2><span class="badge ${r.meets_target===true?'approved':'pending'}">${r.state!=='estimated'?'Cotação pendente':r.meets_target===null?'Estimativa':r.meets_target?'Meta atingida':'Abaixo da meta'}</span></div><div class="restock-stats">${[['Preço de venda',r.price],['Tarifa total Mercado Livre',r.sale_fee],['Frete estimado do vendedor',r.seller_shipping_estimate],['Aquisição',r.acquisition_cost],['Sobra estimada',r.remaining_estimate]].map(([label,value])=>`<div><small>${label}</small><b>${amount(value)}</b></div>`).join('')}</div><p>Margem estimada: <b>${esc(r.remaining_margin_percent??'—')}%</b> · Sua meta: <b>${esc(r.minimum_margin??'—')}%</b></p>${r.issues.length?'<ul class="muted">'+r.issues.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':''}<p class="muted">${esc(r.notice)} As cobranças efetivas aparecem em Financeiro quando a venda é importada. Impostos próprios não informados pela API não estão confirmados nesta estimativa.</p><small>Fonte: ${esc(r.source)} · ${date(r.fetched_at)}</small><div class="toolbar"><button class="secondary" data-proceeds="${r.product_id}">Atualizar cotação atual</button></div></article>`;}
async function loadSellerProceeds(){sellerProceeds=await api('/seller-proceeds');$('proceedsRows').innerHTML=sellerProceeds.map(proceedsCard).join('')||'<p class="muted">Importe seus anúncios para consultar quanto sobra.</p>';renderCatalog();}
async function calculateProceeds(product_id,price){let body={product_id:Number(product_id)};if(price)body.price=price;let r=await api('/seller-proceeds/quote','POST',body);$('proceedsResult').innerHTML=proceedsCard(r);await loadSellerProceeds();await loadStoreDashboard();notice('Cotação consultada. O preço do anúncio foi preservado.');}
$('proceedsForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let values=Object.fromEntries(new FormData(e.target));await calculateProceeds(values.product_id,values.price)}finally{b.disabled=false}})};
$('proceedsGoal').onclick=()=>run(async()=>{let id=Number($('proceedsProduct').value);if(!id)throw Error('Selecione um produto para definir a meta.');let r=sellerProceeds.find(x=>x.product_id===id);openEditor('Sua meta de margem',[{name:'minimum_margin',label:'Margem mínima sobre o preço de venda (%)',type:'number',min:0,max:99,value:r?.minimum_margin??''}],async values=>{await api('/seller-proceeds/products/'+id+'/goal','PUT',values);await loadSellerProceeds();$('proceedsResult').innerHTML='';notice('Meta de margem salva.');});});
document.addEventListener('click',e=>{let b=e.target.closest('[data-proceeds]');if(!b)return;showTab('pricing');$('proceedsProduct').value=b.dataset.proceeds;$('proceedsForm').elements.price.value='';run(async()=>{b.disabled=true;try{await calculateProceeds(b.dataset.proceeds)}finally{b.disabled=false}});});

let listingCurrent=null,listingPlans=[],listingReviewPlan=null,listingWriteEnabled=false,listingCategory=null;
const listingLabels={price:'Preço de venda',quantity:'Quantidade anunciada',status:'Pausar ou reativar',title:'Título',family_name:'Nome da família',pictures:'Fotos e ordem da galeria',description:'Descrição',publish:'Publicar novo produto'};
const listingStates={pending:'Aguardando revisão',executing:'Em conferência ou envio',succeeded:'Conferida no Mercado Livre',sent:'Envio registrado; conferir resultado',partial:'Concluída parcialmente',unknown:'Resultado ainda não confirmado',failed:'Não concluída',conflict:'Prepare uma nova revisão',expired:'Revisão expirada',rejected:'Rejeitada'};
async function loadListingPlans(){let [status,plans]=await Promise.all([api('/listing-manager/status'),api('/listing-manager/plans')]);listingPlans=plans;listingWriteEnabled=status.write_enabled&&status.permissions?.listing_write!=='read_only';$('listingPermissions').textContent=(status.permissions?.listing_write==='read_only'?'Publicação/sincronização está somente leitura no aplicativo. ':status.permissions?.listing_write==='configured'?'Escrita configurada no aplicativo; a autorização e as regras de cada recurso serão conferidas no envio. ':'Permissão específica de escrita ainda não conferida. ')+(status.permissions?.notice||'');$('listingManagerStatus').textContent=(status.write_enabled?'Executor preparado; o envio depende da sua aprovação e das permissões do Mercado Livre.':'Envio desativado; você pode preparar revisões.')+' '+status.automation_notice;$('listingPlans').innerHTML=plans.map(p=>`<article class="card"><div class="card-heading"><h3>#${p.id} · ${esc(listingLabels[p.operation]||p.operation)}</h3><span class="badge ${p.state==='succeeded'?'approved':'pending'}">${esc(listingStates[p.state]||p.state)}</span></div><p>${esc(p.item_id||'Novo anúncio')} · ${date(p.created_at)}</p><p class="muted">${esc(p.note)}</p><p>${esc(p.reason)}</p><details><summary>Valores da proposta</summary><pre class="listing-json">${esc(JSON.stringify({atual:p.before,proposto:p.after},null,2))}</pre></details><div class="toolbar">${p.state==='pending'?`<button data-listing-review="${p.id}">Revisar alteração</button><button data-listing-reject="${p.id}" class="secondary">Rejeitar</button>`:''}${['executing','unknown','sent','partial','succeeded'].includes(p.state)?`<button data-listing-verify="${p.id}" class="secondary">Conferir resultado</button>`:''}</div></article>`).join('')||'<div class="card"><p class="muted">Nenhuma alteração real preparada. As aprovações simuladas antigas continuam separadas.</p></div>';}
async function selectListing(){listingCurrent=null;$('listingEditor').hidden=true;let id=+$('listingProduct').value;if(!id){$('listingCurrent').textContent='Selecione um anúncio importado.';return;}$('listingCurrent').textContent='Consultando o anúncio atual no Mercado Livre…';let item=await api('/listing-manager/products/'+id);if(+$('listingProduct').value!==id)return;listingCurrent=item;$('listingCurrent').textContent=`${item.id} · ${item.title}\n${currencyAmount(item.price,item.currency_id)} · ${item.available_quantity??'—'} unidade(s) · ${item.status}\n${item.notice}`;let allowed=Object.entries(item.capabilities).filter(([,available])=>available);$('listingOperation').innerHTML=allowed.map(([key])=>`<option value="${key}">${esc(listingLabels[key])}</option>`).join('');$('listingEditor').hidden=!allowed.length;renderListingInput();}
function renderListingInput(){let i=listingCurrent;if(!i)return;let op=$('listingOperation').value,field='';if(op==='price')field=`<input name="price" type="number" min="0.01" max="10000000" step="0.01" value="${esc(i.price)}" required>`;if(op==='quantity')field=`<input name="quantity" type="number" min="0" max="1000000" step="1" value="${esc(i.available_quantity)}" required>`;if(op==='status')field=`<select name="status"><option value="paused" ${i.status==='active'?'selected':''}>Pausado</option><option value="active" ${i.status==='paused'?'selected':''}>Ativo</option></select>`;if(['title','family_name'].includes(op))field=`<input name="${op}" minlength="3" maxlength="120" value="${esc(i[op])}" required>`;if(op==='description')field=`<textarea name="description" rows="6" maxlength="50000">${esc(i.description)}</textarea>`;if(op==='pictures')field=`<textarea name="pictures" rows="6" required>${i.pictures.map(p=>esc(p.id)).join('\n')}</textarea><small>Mantenha os identificadores na ordem desejada. Para novas fotos, use uma URL HTTPS pública por linha. A lista substitui a galeria atual.</small>`;$('listingValueFields').innerHTML=`<label>${esc(listingLabels[op])}${field}</label>`;}
$('listingProduct').onchange=()=>run(selectListing);$('listingOperation').onchange=renderListingInput;
function pictureLines(text){return text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).map(s=>s.startsWith('https://')?{source:s}:{id:s});}
$('listingEditForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let values=Object.fromEntries(new FormData(e.target));if(values.operation==='quantity')values.quantity=Number(values.quantity);if(values.operation==='pictures')values.pictures=pictureLines(values.pictures);let p=await api('/listing-manager/products/'+$('listingProduct').value+'/plans','POST',values);await loadListingPlans();openListingReview(p.id);}finally{b.disabled=false}});};
function openListingReview(id){let p=listingPlans.find(p=>p.id===Number(id));if(!p)return;listingReviewPlan=p;$('listingConsent').checked=false;$('executeListing').disabled=!listingWriteEnabled;$('listingReviewContent').innerHTML=`<p><b>${esc(listingLabels[p.operation])}</b> · ${esc(p.item_id||'Novo anúncio real')}</p><p>${esc(p.notice)}</p><p>Motivo: ${esc(p.reason)}</p><h3>Antes</h3><pre>${esc(JSON.stringify(p.before,null,2))}</pre><h3>O que será enviado</h3><pre>${esc(JSON.stringify(p.after,null,2))}</pre>${p.description?'<h3>Descrição após criar o anúncio</h3><pre>'+esc(p.description)+'</pre>':''}${p.margin?`<p><b>Sobra estimada: ${esc(currencyAmount(p.margin.remaining_estimate,'BRL'))}</b> · margem ${esc(p.margin.remaining_margin_percent)}% · meta ${esc(p.margin.minimum_margin)}%</p>`:''}<p class="muted">Revisão válida até ${date(p.expires_at)}. Alterações no anúncio ou nos custos exigem uma nova revisão.</p>`;$('listingReview').showModal();}
$('closeListingReview').onclick=()=>$('listingReview').close();$('listingReviewForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=$('executeListing');b.disabled=true;try{if(!$('listingConsent').checked||!listingReviewPlan)return;let p=await api('/listing-manager/plans/'+listingReviewPlan.id+'/execute','POST',{review_hash:listingReviewPlan.review_hash});$('listingReview').close();await load();notice(p.note,p.state!=='succeeded');if($('listingProduct').value)await selectListing();}finally{b.disabled=!listingWriteEnabled}});};
$('refreshListingPlans').onclick=()=>run(loadListingPlans);
$('checkListingPermissions').onclick=()=>run(async()=>{let b=$('checkListingPermissions');b.disabled=true;try{await api('/listing-manager/permissions/check','POST');await loadListingPlans();notice('Permissões consultadas no Mercado Livre. Confira a orientação no painel.');}finally{b.disabled=false}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.manageListing){showTab('listings');$('listingProduct').value=b.dataset.manageListing;run(selectListing);}if(b.dataset.listingReview)openListingReview(b.dataset.listingReview);if(b.dataset.listingReject)run(async()=>{let p=listingPlans.find(p=>p.id===+b.dataset.listingReject);await api('/listing-manager/plans/'+p.id+'/reject','POST',{review_hash:p.review_hash});await loadListingPlans();notice('Revisão rejeitada. Nada foi enviado.');});if(b.dataset.listingVerify)run(async()=>{b.disabled=true;try{let r=await api('/listing-manager/plans/'+b.dataset.listingVerify+'/verify','POST');await load();notice(r.note,r.state!=='succeeded');}finally{b.disabled=false}});if(b.dataset.category){$('publishCategory').value=b.dataset.category;run(loadListingCategory);}});
$('categorySearchForm').onsubmit=e=>{e.preventDefault();run(async()=>{let rows=await api('/listing-manager/categories/search?q='+encodeURIComponent($('categoryQuery').value));$('categorySuggestions').innerHTML=rows.map(c=>`<button type="button" class="secondary" data-category="${esc(c.category_id)}">${esc(c.category_name)} · ${esc(c.category_id)}</button>`).join('')||'<p>Nenhuma sugestão encontrada.</p>';});};
async function loadListingCategory(){let id=$('publishCategory').value.trim();let c=await api('/listing-manager/categories/'+encodeURIComponent(id));listingCategory=id;$('publishAttributes').innerHTML='<p class="muted">'+esc(c.name)+' · Preencha as características que correspondem ao produto. A validação da API apontará exigências adicionais.</p>'+c.attributes.map((a,index)=>`<label>${esc(a.name||a.id)}${a.required?' *':''}<input data-listing-attribute="${esc(a.id)}" maxlength="500" ${a.required?'required':''} ${a.values.length?'list="listing-attr-'+index+'"':''}>${a.values.length?`<datalist id="listing-attr-${index}">${a.values.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`:''}</label>`).join('');}
$('loadCategory').onclick=()=>run(loadListingCategory);$('publishCategory').oninput=()=>{listingCategory=null;$('publishAttributes').innerHTML='<p class="muted">Carregue os atributos desta categoria antes de continuar.</p>';};
$('publishForm').onsubmit=e=>{e.preventDefault();run(async()=>{let b=e.submitter;b.disabled=true;try{let values=Object.fromEntries(new FormData(e.target));if(values.category_id!==listingCategory)throw Error('Carregue os atributos da categoria antes de preparar a publicação.');values.quantity=Number(values.quantity);values.free_shipping=values.free_shipping==='true';values.pictures=pictureLines(values.pictures);values.attributes=[...$('publishAttributes').querySelectorAll('[data-listing-attribute]')].filter(i=>i.value.trim()).map(i=>({id:i.dataset.listingAttribute,value_name:i.value.trim()}));values.sale_terms=[];if(values.warranty_type)values.sale_terms.push({id:'WARRANTY_TYPE',value_name:values.warranty_type});if(values.warranty_time)values.sale_terms.push({id:'WARRANTY_TIME',value_name:values.warranty_time});delete values.warranty_type;delete values.warranty_time;let p=await api('/listing-manager/publish/plans','POST',values);await loadListingPlans();openListingReview(p.id);}finally{b.disabled=false}});};

run(load);

function renderArchivedCatalog(){let rows=state.archivedCatalog||[];$('archivedCatalogCount').textContent='('+rows.length+')';$('archivedCatalogRows').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Estado no Mercado Livre</th><th>Última conferência</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku)}</small></td><td>${esc(({closed:'Encerrado',deleted:'Excluído',not_found:'Remoção confirmada'})[p.marketplace_status]||p.marketplace_status)}</td><td>${date(p.status_checked_at)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum anúncio arquivado.</p>';}
